<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Oidc\Registration\Application\Usecase\ReadClientRegistration;

use Civi\Lughauth\Features\Oidc\Registration\Domain\ClientRegistrationData;
use Civi\Lughauth\Features\Oidc\Registration\Domain\Gateway\ClientRegistrationGateway;
use Civi\Lughauth\Features\Oidc\Registration\Domain\Exception\RegistrationException;

final class ReadClientRegistrationUsecase
{
    public function __construct(
        private readonly ClientRegistrationGateway $gateway,
    ) {
    }

    public function read(string $clientId, string $registrationAccessToken): ClientRegistrationData
    {
        $data = $this->gateway->findByClientIdAndToken($clientId, $registrationAccessToken);
        if ($data === null) {
            throw RegistrationException::invalidToken();
        }
        return $data;
    }
}
